/* Todavía Business Manager v7 — mòdul de gestió de petit negoci
   Offline-first. Les dades d'aquest mòdul viuen al dispositiu i es poden sincronitzar a Google Sheets/Drive.
*/
(function(){
'use strict';
const BMKEY='todavia_business_v9';
const VAT=[0,4,10,21];
let bm=loadBM();
let bmTab='resum';
function def(){return {version:9,company:{name:'Todavía',legalName:'',nif:'',address:'',city:'',postalCode:'',email:'',phone:'',iban:'',invoicePrefix:'F',invoiceNext:1,defaultVat:21,invoiceFooter:'Gràcies per la teva confiança.',taxRegime:'general',irpfMethod:'directa',irpfRetention:0,vatEnabled:true,vatSettlement:'trimestral',intraEU:false,sifMode:'verifactu',sifDefaultApplicable:true},customers:[],shopDays:[],workshops:[],invoices:[],expenses:[],purchaseInvoices:[],cash:[],settings:{driveFolderId:'',sheetPrefix:'',emailMode:'share'},verifactu:{records:[],events:[],lastHash:'',nextNumber:1,sequenceYear:new Date().getFullYear()},pending:[]}}
function loadBM(){try{return Object.assign(def(),JSON.parse(localStorage.getItem(BMKEY)||'{}'),{company:Object.assign(def().company,JSON.parse(localStorage.getItem(BMKEY)||'{}').company||{})})}catch(e){return def()}}
function saveBM(){localStorage.setItem(BMKEY,JSON.stringify(bm))}
function uid(p){return p+'_'+(crypto.randomUUID?crypto.randomUUID():Date.now()+'_'+Math.random().toString(36).slice(2))}
function eur(n){return (Number(n)||0).toLocaleString('ca-ES',{style:'currency',currency:'EUR'})}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function today(){return new Date().toISOString().slice(0,10)}
function fmtDate(d){if(!d)return '—';return new Date(d+'T12:00:00').toLocaleDateString('ca-ES')}
function toast(t){if(window.showToast)showToast(t);else alert(t)}
function ensureUI(){
 const drawer=document.getElementById('drawer'); if(!drawer)return;
 if(!document.getElementById('nav-business')){
  const b=document.createElement('button');b.type='button';b.className='nav-item';b.id='nav-business';b.innerHTML='<span>🧰 Gestió negoci</span><span class="nav-badge" id="nb-business">—</span>';b.onclick=()=>openBusiness();
  const shop=document.createElement('button');shop.type='button';shop.className='nav-item';shop.id='nav-shop-direct';shop.innerHTML='<span>🏪 Botiga física</span>';shop.onclick=()=>{openBusiness();bmTab='botiga';renderBM()};
  const work=document.createElement('button');work.type='button';work.className='nav-item';work.id='nav-workshop-direct';work.innerHTML='<span>🎨 Tallers</span>';work.onclick=()=>{openBusiness();bmTab='tallers';renderBM()};
  const bill=document.createElement('button');bill.type='button';bill.className='nav-item';bill.id='nav-billing-direct';bill.innerHTML='<span>🧾 Facturació</span>';bill.onclick=()=>{openBusiness();bmTab='factures';renderBM()};
  const cfg=document.getElementById('nav-config'); if(cfg){drawer.insertBefore(b,cfg);drawer.insertBefore(shop,cfg);drawer.insertBefore(work,cfg);drawer.insertBefore(bill,cfg);} else {drawer.appendChild(b);drawer.appendChild(shop);drawer.appendChild(work);}
 }
 if(document.getElementById('section-business'))return;
 const wrap=document.querySelector('.wrapper');
 const sec=document.createElement('div');sec.className='section';sec.id='section-business';sec.innerHTML=html();wrap.appendChild(sec);
 bind();renderBM();
}
function html(){return `
<div class="section-header"><div><div class="section-title">🧰 Gestió del negoci</div><div class="section-subtitle">Mercats · botiga · tallers · factures · clients · despeses · caixa</div></div><button class="btn btn-primary" onclick="BM.quickSave()">💾 Guardar</button></div>
<div class="bm-tabs">${[['resum','📊 Resum'],['botiga','🏪 Botiga'],['tallers','🎨 Tallers'],['factures','🧾 Factures'],['clients','👥 Clients'],['despeses','💸 Despeses'],['compres','📥 Compres'],['caixa','💶 Caixa'],['fiscal','🧮 Fiscalitat'],['verifactu','🧾 VERI*FACTU'],['empresa','⚙ Empresa']].map(x=>`<button data-bmtab="${x[0]}">${x[1]}</button>`).join('')}</div>
<div id="bm-content"></div>`}
function openBusiness(){ensureUI();document.querySelectorAll('.section').forEach(s=>s.classList.remove('active'));document.getElementById('section-business').classList.add('active');document.querySelectorAll('.nav-item').forEach(n=>n.classList.remove('active'));document.getElementById('nav-business').classList.add('active');closeDrawerSafe();renderBM()}
function closeDrawerSafe(){if(window.closeDrawer)window.closeDrawer()}
function bind(){document.querySelectorAll('[data-bmtab]').forEach(b=>b.onclick=()=>{bmTab=b.dataset.bmtab;renderBM()})}
function renderBM(){ensureUI();const c=document.getElementById('bm-content');if(!c)return;document.querySelectorAll('[data-bmtab]').forEach(b=>b.classList.toggle('active',b.dataset.bmtab===bmTab));c.innerHTML=({resum:resum,botiga:botiga,tallers:tallers,factures:factures,clients:clients,despeses:despeses,compres:compres,caixa:caixa,fiscal:fiscal,verifactu:verifactu,empresa:empresa}[bmTab]||resum)();
 if(bmTab==='fiscal')renderFiscal(); if(bmTab==='factures')renderInvoiceRows(); if(bmTab==='clients')renderClientRows(); if(bmTab==='tallers')renderWorkshopRows(); if(bmTab==='despeses')renderExpenseRows(); if(bmTab==='compres')renderPurchaseRows(); if(bmTab==='caixa')renderCashRows();
}
function card(t,b){return `<div class="panel"><div class="panel-header"><span class="panel-title">${t}</span></div><div style="padding:14px">${b}</div></div>`}
function resum(){const rev=bm.invoices.filter(i=>i.status!=='cancel·lada').reduce((s,i)=>s+i.total,0);const exp=bm.expenses.reduce((s,x)=>s+x.amount,0);const shop=bm.shopDays.filter(x=>x.closed).reduce((s,x)=>s+x.sales,0);const workshops=bm.workshops.reduce((s,w)=>s+(w.sessions||[]).reduce((a,x)=>a+x.net,0),0);const pending=bm.pending.length;return `<div class="fin-grid2"><div class="fin-big"><div class="fin-big-label">Factures emeses</div><div class="fin-big-val accent">${bm.invoices.length}</div></div><div class="fin-big"><div class="fin-big-label">Facturació factures</div><div class="fin-big-val green">${eur(rev)}</div></div><div class="fin-big"><div class="fin-big-label">Botiga acumulada</div><div class="fin-big-val blue">${eur(shop)}</div></div><div class="fin-big"><div class="fin-big-label">Benefici tallers</div><div class="fin-big-val purple">${eur(workshops)}</div></div></div>${card('Activitat',`<div class="bm-kpis"><div><b>${bm.shopDays.length}</b><span>dies de botiga</span></div><div><b>${bm.workshops.length}</b><span>tallers</span></div><div><b>${bm.customers.length}</b><span>clients</span></div><div><b>${eur(exp)}</b><span>despeses</span></div></div>`)}${card('Sincronització',`<div class="between"><span>${pending?`⚠️ ${pending} elements pendents`:'✓ Tot guardat localment'}</span><button class="btn btn-primary" onclick="BM.syncAll()">↑ Sincronitzar negoci</button></div>`)}${card('Accions ràpides',`<div class="actions"><button class="btn btn-primary" onclick="BM.newInvoice()">+ Factura</button><button class="btn btn-ghost" onclick="BM.openShop()">🏪 Obrir botiga avui</button><button class="btn btn-ghost" onclick="BM.newWorkshop()">+ Taller</button><button class="btn btn-ghost" onclick="BM.newExpense()">+ Despesa</button></div>`)}`}
function shopProducts(){try{return (catalogue||[]).filter(p=>p.active).map(p=>({name:p.name||p.label||p.product||'Producte',price:+p.pvp||0,cost:+p.cost||0,sourceId:p.id||''})).filter(p=>p.price>0)}catch(e){return []}}
function shopCalcRender(){const wrap=document.getElementById('shopCalcLines');if(!wrap)return;const rows=[...wrap.querySelectorAll('.shop-calc-row')];let total=0;rows.forEach(r=>{const q=Math.max(1,+r.querySelector('.shop-calc-qty').value||1);const price=+r.dataset.price||0;const line=q*price;total+=line;r.querySelector('.shop-calc-line').textContent=eur(line);r.dataset.lineTotal=line;r.querySelector('.shop-calc-qty').value=q});const t=document.getElementById('shopCalcTotal');if(t)t.textContent=eur(total);const n=document.getElementById('shopCalcCount');if(n)n.textContent=rows.length+' productes';return total}
function shopCalcAdd(product){const wrap=document.getElementById('shopCalcLines');if(!wrap)return;const existing=[...wrap.querySelectorAll('.shop-calc-row')].find(r=>r.dataset.sourceId===product.sourceId&&r.dataset.name===product.name);if(existing){existing.querySelector('.shop-calc-qty').value=(+existing.querySelector('.shop-calc-qty').value||1)+1;shopCalcRender();return}const row=document.createElement('div');row.className='shop-calc-row';row.dataset.sourceId=product.sourceId;row.dataset.name=product.name;row.dataset.price=product.price;row.dataset.lineTotal=product.price;row.innerHTML=`<div style="flex:1;min-width:0"><b>${esc(product.name)}</b><div class="muted">${eur(product.price)} / unitat</div></div><input class="shop-calc-qty" type="number" min="1" step="1" value="1" style="width:64px" oninput="BM.shopCalcRender()"><b class="shop-calc-line">${eur(product.price)}</b><button class="btn btn-ghost" style="padding:5px 8px" onclick="this.closest('.shop-calc-row').remove();BM.shopCalcRender()">×</button>`;wrap.appendChild(row);shopCalcRender()}
function shopCalcClear(){const w=document.getElementById('shopCalcLines');if(w)w.innerHTML='';shopCalcRender()}
function shopCalcCheckout(id){const d=bm.shopDays.find(x=>x.id===id);if(!d)return;const rows=[...document.querySelectorAll('#shopCalcLines .shop-calc-row')];if(!rows.length)return toast('Afegeix almenys un producte');const lines=rows.map(r=>({productId:r.dataset.sourceId||'',description:r.dataset.name,qty:Math.max(1,+r.querySelector('.shop-calc-qty').value||1),price:+r.dataset.price||0,total:+r.dataset.lineTotal||0}));const total=lines.reduce((s,x)=>s+x.total,0);const method=document.getElementById('shopCalcMethod')?.value||'Efectiu';d.sales=+(d.sales+total).toFixed(2);d.movements=d.movements||[];d.movements.push({id:uid('sm'),type:'sale',amount:total,method,description:lines.map(x=>`${x.qty}× ${x.description}`).join(', '),lines,createdAt:new Date().toISOString()});saveBM();shopCalcClear();renderBM();toast(`Venda registrada: ${eur(total)}`)}
function shopCalcCustom(){const name=prompt('Nom del producte');if(!name)return;const price=parseFloat(prompt('Preu unitari (€)'));if(!(price>0))return toast('Preu invàlid');shopCalcAdd({name,price,cost:0,sourceId:'custom_'+uid('p')})}
function shopCalcPanel(open){const products=shopProducts();return `<div class="shop-calc"><div class="between"><div><b>🧮 Calculadora de venda</b><div class="muted">Afegeix diversos productes, ajusta quantitats i cobra el total.</div></div><button class="btn btn-ghost" onclick="BM.shopCalcClear()">Netejar</button></div><div class="shop-product-buttons">${products.map(p=>`<button class="btn btn-ghost" onclick='BM.shopCalcAdd(${JSON.stringify(p)})'>+ ${esc(p.name)} · ${eur(p.price)}</button>`).join('')}<button class="btn btn-ghost" onclick="BM.shopCalcCustom()">+ Producte manual</button></div><div id="shopCalcLines" class="shop-calc-lines"></div><div class="shop-calc-total"><span><span id="shopCalcCount">0 productes</span> · TOTAL</span><strong id="shopCalcTotal">0,00 €</strong></div><div class="row" style="margin-top:10px"><div class="field"><label>Mètode de pagament</label><select id="shopCalcMethod"><option>Efectiu</option><option>Targeta</option><option>Bizum</option></select></div><div class="actions" style="align-items:end"><button class="btn btn-primary" onclick="BM.shopCalcCheckout('${open.id}')">✓ Cobrar i comptabilitzar</button></div></div></div>`}
function botiga(){const open=bm.shopDays.find(x=>x.date===today()&&!x.closed);const days=bm.shopDays.slice().reverse();return card('🏪 Botiga física',`${open?`<div><div class="between"><div><b>Botiga oberta avui</b><div class="muted">Inici ${new Date(open.openedAt).toLocaleTimeString('ca-ES',{hour:'2-digit',minute:'2-digit'})}</div></div><button class="btn btn-primary" onclick="BM.closeShop('${open.id}')">Tancar dia</button></div><div class="actions" style="margin-top:10px"><button class="btn btn-ghost" onclick="BM.shopSale('${open.id}')">+ Venda ràpida</button><button class="btn btn-ghost" onclick="BM.shopCost('${open.id}')">+ Cost botiga</button></div>${shopCalcPanel(open)}<div style="margin-top:10px"><b>Avui: ${eur(open.sales)} vendes · ${eur(open.costs)} costos · ${eur(open.sales-open.costs)} net</b></div></div>`:`<div class="actions"><button class="btn btn-primary" onclick="BM.openShop()">Obrir botiga avui</button></div>`}`)+card('Historial botiga',`<div class="table-scroll"><table><thead><tr><th>Data</th><th>Vendes</th><th>Costos</th><th>Net</th><th>Estat</th></tr></thead><tbody>${days.map(d=>`<tr><td>${fmtDate(d.date)}</td><td>${eur(d.sales)}</td><td>${eur(d.costs)}</td><td>${eur(d.sales-d.costs)}</td><td>${d.closed?'Tancat':'Obert'}</td></tr>`).join('')||'<tr><td colspan="5">Sense dies</td></tr>'}</tbody></table></div>`)}

function tallers(){return card('🎨 Tallers',`<div class="actions"><button class="btn btn-primary" onclick="BM.newWorkshop()">+ Nou taller</button></div><div id="bm-workshops" style="margin-top:12px"></div>`)}
function factures(){return card('🧾 Facturació',`<div class="actions"><button class="btn btn-primary" onclick="BM.newInvoice()">+ Nova factura</button><button class="btn btn-ghost" onclick="BM.exportInvoicesCSV()">↓ CSV</button></div><div class="field" style="margin-top:12px"><input id="invoiceSearch" placeholder="Buscar per número o client" oninput="BM.renderInvoiceRows()"></div><div id="bm-invoices"></div>`)}
function clients(){return card('👥 Clients',`<div class="actions"><button class="btn btn-primary" onclick="BM.newClient()">+ Client</button></div><div id="bm-clients" style="margin-top:12px"></div>`)}
function despeses(){return card('💸 Despeses',`<div class="actions"><button class="btn btn-primary" onclick="BM.newExpense()">+ Despesa</button></div><div id="bm-expenses" style="margin-top:12px"></div>`)}
function compres(){return card('📥 Factures de compra',`<div class="actions"><button class="btn btn-primary" onclick="BM.newPurchase()">+ Factura de proveïdor</button></div><div id="bm-purchases" style="margin-top:12px"></div>`)}
function caixa(){const bal=bm.cash.reduce((s,x)=>s+(x.type==='in'?x.amount:-x.amount),0);return card('💶 Caixa',`<div class="fin-grid2"><div class="fin-big"><div class="fin-big-label">Saldo moviment</div><div class="fin-big-val green">${eur(bal)}</div></div><div class="fin-big"><div class="fin-big-label">Moviments</div><div class="fin-big-val blue">${bm.cash.length}</div></div></div><div class="actions"><button class="btn btn-primary" onclick="BM.newCash('in')">+ Entrada</button><button class="btn btn-ghost" onclick="BM.newCash('out')">− Sortida</button></div><div id="bm-cash" style="margin-top:12px"></div>`)}
function empresa(){const c=bm.company;return card('⚙ Dades de l’empresa',`<div class="cfg-grid"><div><div class="field"><label>Nom comercial</label><input id="coName" value="${esc(c.name)}"></div><div class="field"><label>Raó social</label><input id="coLegal" value="${esc(c.legalName)}"></div><div class="field"><label>NIF/CIF</label><input id="coNif" value="${esc(c.nif)}"></div><div class="field"><label>Adreça</label><input id="coAddress" value="${esc(c.address)}"></div><div class="row"><div class="field"><label>CP</label><input id="coPostal" value="${esc(c.postalCode)}"></div><div class="field"><label>Ciutat</label><input id="coCity" value="${esc(c.city)}"></div></div></div><div><div class="field"><label>Email</label><input id="coEmail" type="email" value="${esc(c.email)}"></div><div class="field"><label>Telèfon</label><input id="coPhone" value="${esc(c.phone)}"></div><div class="field"><label>IBAN</label><input id="coIban" value="${esc(c.iban)}"></div><div class="row"><div class="field"><label>Prefix factura</label><input id="coPrefix" value="${esc(c.invoicePrefix)}"></div><div class="field"><label>IVA per defecte</label><select id="coVat">${VAT.map(v=>`<option ${v===c.defaultVat?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field"><label>Peu de factura</label><textarea id="coFooter">${esc(c.invoiceFooter)}</textarea></div><button class="btn btn-primary" onclick="BM.saveCompany()">Guardar empresa</button><div class="actions" style="margin-top:10px"><button class="btn btn-ghost" onclick="BM.exportData()">↓ Exportar gestió</button><label class="btn btn-ghost">↑ Importar gestió<input type="file" accept="application/json" onchange="BM.importData(event)" style="display:none"></label></div></div></div>`)}
function renderInvoiceRows(){const el=document.getElementById('bm-invoices');if(!el)return;const q=(document.getElementById('invoiceSearch')?.value||'').toLowerCase();const arr=bm.invoices.filter(i=>(i.number+' '+(i.customerName||'')).toLowerCase().includes(q)).slice().reverse();el.innerHTML=`<div class="table-scroll"><table><thead><tr><th>Número</th><th>Data</th><th>Client</th><th>Base</th><th>IVA</th><th>IRPF</th><th>Total</th><th>VERI*FACTU</th><th>Estat</th><th></th></tr></thead><tbody>${arr.map(i=>`<tr><td><b>${esc(i.number)}</b></td><td>${fmtDate(i.date)}</td><td>${esc(i.customerName||'—')}</td><td>${eur(i.subtotal)}</td><td>${eur(i.tax)}</td><td>${i.irpfAmount?'-'+eur(i.irpfAmount):'—'}</td><td>${eur(i.total)}</td><td>${i.sifApplicable?esc(i.verifactuStatus||'pendent'):'Fora d’àmbit'}</td><td>${esc(i.status)}</td><td><button class="btn btn-ghost" onclick="BM.invoiceActions('${i.id}')">•••</button></td></tr>`).join('')||'<tr><td colspan="10">Sense factures</td></tr>'}</tbody></table></div>`}
function renderClientRows(){const el=document.getElementById('bm-clients');if(!el)return;el.innerHTML=`<div class="table-scroll"><table><thead><tr><th>Client</th><th>NIF</th><th>Email</th><th></th></tr></thead><tbody>${bm.customers.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.nif)}</td><td>${esc(c.email)}</td><td><button class="btn btn-ghost" onclick="BM.editClient('${c.id}')">Editar</button></td></tr>`).join('')||'<tr><td colspan="4">Sense clients</td></tr>'}</tbody></table></div>`}
function renderWorkshopRows(){const el=document.getElementById('bm-workshops');if(!el)return;el.innerHTML=bm.workshops.map(w=>{const net=(w.sessions||[]).reduce((s,x)=>s+x.net,0);return `<div class="item-card"><div class="between"><div><b>${esc(w.name)}</b><div class="muted">${w.paxMin||0}–${w.paxMax||0} pax · ${eur(w.pricePerPax||0)}/pax</div></div><b class="positive">${eur(net)}</b></div><div class="actions" style="margin-top:8px"><button class="btn btn-ghost" onclick="BM.addWorkshopSession('${w.id}')">+ Sessió</button><button class="btn btn-ghost" onclick="BM.editWorkshop('${w.id}')">Editar</button></div></div>`}).join('')||'<div class="empty-state">Encara no hi ha tallers</div>'}
function renderExpenseRows(){const el=document.getElementById('bm-expenses');if(!el)return;el.innerHTML=`<div class="table-scroll"><table><thead><tr><th>Data</th><th>Concepte</th><th>Categoria</th><th>Import</th></tr></thead><tbody>${bm.expenses.slice().reverse().map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.description)}</td><td>${esc(x.category)}</td><td>${eur(x.amount)}</td></tr>`).join('')||'<tr><td colspan="4">Sense despeses</td></tr>'}</tbody></table></div>`}
function renderPurchaseRows(){const el=document.getElementById('bm-purchases');if(!el)return;el.innerHTML=`<div class="table-scroll"><table><thead><tr><th>Data</th><th>Proveïdor</th><th>Número</th><th>Total</th></tr></thead><tbody>${bm.purchaseInvoices.slice().reverse().map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.supplier)}</td><td>${esc(x.number)}</td><td>${eur(x.total)}</td></tr>`).join('')||'<tr><td colspan="4">Sense compres</td></tr>'}</tbody></table></div>`}
function renderCashRows(){const el=document.getElementById('bm-cash');if(!el)return;el.innerHTML=`<div class="table-scroll"><table><thead><tr><th>Data</th><th>Concepte</th><th>Tipus</th><th>Import</th></tr></thead><tbody>${bm.cash.slice().reverse().map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.description)}</td><td>${x.type==='in'?'Entrada':'Sortida'}</td><td>${eur(x.amount)}</td></tr>`).join('')||'<tr><td colspan="4">Sense moviments</td></tr'}</tbody></table></div>`}
function formModal(title,body,save){let old=document.getElementById('bmModal');if(old)old.remove();const d=document.createElement('div');d.className='modal-backdrop open';d.id='bmModal';d.innerHTML=`<div class="modal" style="max-width:680px;max-height:90vh;overflow:auto"><h2>${title}</h2>${body}<div class="modal-actions"><button class="btn btn-ghost" onclick="BM.closeModal()">Cancel·lar</button><button class="btn btn-primary" id="bmSave">Guardar</button></div></div>`;document.body.appendChild(d);d.querySelector('#bmSave').onclick=save}
function newClient(existing){const c=existing||{};formModal(existing?'Editar client':'Nou client',`<div class="field"><label>Nom / empresa</label><input id="fName" value="${esc(c.name)}"></div><div class="row"><div class="field"><label>NIF/CIF</label><input id="fNif" value="${esc(c.nif)}"></div><div class="field"><label>Email</label><input id="fEmail" value="${esc(c.email)}"></div></div><div class="field"><label>Adreça</label><input id="fAddress" value="${esc(c.address)}"></div><div class="row"><div class="field"><label>CP</label><input id="fPostal" value="${esc(c.postalCode)}"></div><div class="field"><label>Ciutat</label><input id="fCity" value="${esc(c.city)}"></div></div>`,()=>{const o={id:c.id||uid('cli'),name:document.getElementById('fName').value.trim(),nif:document.getElementById('fNif').value.trim(),email:document.getElementById('fEmail').value.trim(),address:document.getElementById('fAddress').value.trim(),postalCode:document.getElementById('fPostal').value.trim(),city:document.getElementById('fCity').value.trim()};if(!o.name)return toast('Falta el nom');const ix=bm.customers.findIndex(x=>x.id===o.id);if(ix>=0)bm.customers[ix]=o;else bm.customers.push(o);saveBM();closeModal();renderBM()})}
function newInvoice(existing){
 const inv=existing||{};
 const lines=inv.lines||[{description:'',qty:1,price:0,vat:bm.company.defaultVat}];
 const sif=inv.sifApplicable!==undefined?inv.sifApplicable:bm.company.sifDefaultApplicable!==false;
 const vatTreatment=inv.vatTreatment||'subjecta';
 const irpf=inv.irpfRetention!==undefined?inv.irpfRetention:(bm.company.irpfRetention||0);
 formModal(inv.id?'Editar factura':'Nova factura',`
 <div class="row"><div class="field"><label>Client</label><select id="fClient"><option value="">Client particular</option>${bm.customers.map(c=>`<option value="${c.id}" ${c.id===inv.customerId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Data</label><input id="fDate" type="date" value="${inv.date||today()}"></div></div>
 <div class="field"><label>Concepte / línies (descripció | quantitat | preu | IVA%)</label><textarea id="fLines" style="min-height:130px">${lines.map(l=>`${l.description} | ${l.qty} | ${l.price} | ${l.vat}`).join('\n')}</textarea><div class="small muted">Exemple: Print A4 | 2 | 8 | 21</div></div>
 <div class="row"><div class="field"><label>Tractament IVA</label><select id="fVatTreatment"><option value="subjecta" ${vatTreatment==='subjecta'?'selected':''}>Subjecta</option><option value="exempta" ${vatTreatment==='exempta'?'selected':''}>Exempta</option><option value="no_sujeta" ${vatTreatment==='no_sujeta'?'selected':''}>No subjecta</option></select></div><div class="field"><label>Retenció IRPF (%)</label><input id="fIrpf" type="number" min="0" max="100" step="0.01" value="${irpf}"></div></div>
 <div class="row"><div class="field"><label>Sistema de facturació</label><select id="fSif" onchange="BM.toggleSifFields()"><option value="true" ${sif?'selected':''}>Incloure a VERI*FACTU</option><option value="false" ${!sif?'selected':''}>Fora de l'àmbit RRSIF</option></select></div><div class="field"><label>Estat</label><select id="fStatus"><option value="emesa" ${(inv.status||'emesa')==='emesa'?'selected':''}>Emesa</option><option value="cancel·lada" ${(inv.status||'')==='cancel·lada'?'selected':''}>Cancel·lada</option></select></div></div>
 <div id="sifReasonBox" class="field" style="display:${sif?'none':'block'}"><label>Motiu documentat de fora d'àmbit</label><select id="fSifReason"><option value="">Selecciona un motiu</option><option value="no_factura_obligatoria" ${inv.sifReason==='no_factura_obligatoria'?'selected':''}>No existeix obligació d'expedir factura</option><option value="operacio_exclosa_rssif" ${inv.sifReason==='operacio_exclosa_rssif'?'selected':''}>Operació exclosa de l'àmbit objectiu del RRSIF</option><option value="sii" ${inv.sifReason==='sii'?'selected':''}>Obligat al SII</option><option value="altre" ${inv.sifReason==='altre'?'selected':''}>Altre motiu justificat</option></select><div class="small muted">No utilitzis aquesta opció només perquè l'operació sigui exempta o no subjecta a IVA: aquestes operacions poden continuar havent-se de registrar si existeix obligació de factura.</div></div>
 <div class="field"><label>Notes</label><textarea id="fNotes">${esc(inv.notes||'')}</textarea></div>
 <div class="small muted">El PDF es guarda localment i, quan sincronitzes, també es pot guardar a Drive. VERI*FACTU és només la preparació del registre: aquesta versió encara no envia registres directament a l'AEAT.</div>`,()=>{
   const customer=bm.customers.find(c=>c.id===document.getElementById('fClient').value);
   const parsed=document.getElementById('fLines').value.split('\n').map(x=>x.trim()).filter(Boolean).map(x=>{const a=x.split('|').map(y=>y.trim());return {description:a[0]||'',qty:+a[1]||1,price:+a[2]||0,vat:VAT.includes(+a[3])?+a[3]:bm.company.defaultVat}});
   if(!parsed.length)return toast('Afegeix almenys una línia');
   if(parsed.some(l=>l.qty<=0||l.price<0))return toast('Quantitats o preus invàlids');
   const vatTreatmentNow=document.getElementById('fVatTreatment').value;
   const normalized=parsed.map(l=>({...l,vat:vatTreatmentNow==='subjecta'?l.vat:0}));
   const id=inv.id||uid('inv');
   const sifApplicable=document.getElementById('fSif').value==='true';
   const sifReason=sifApplicable?'':document.getElementById('fSifReason').value;
   if(!sifApplicable&&!sifReason)return toast('Indica el motiu de fora d\'àmbit');
   if(inv.verifactuRecordId&&inv.sifApplicable!==sifApplicable)return toast('No es pot canviar l’àmbit VERI*FACTU d’una factura que ja té registre de facturació. Crea una rectificativa si cal.');
   if(inv.verifactuStatus==='accepted'&&JSON.stringify(inv.lines)!==JSON.stringify(normalized))return toast('Una factura VERI*FACTU acceptada no es pot editar; crea una rectificativa.');
   const subtotal=normalized.reduce((sum,l)=>sum+l.qty*l.price,0);
   const tax=vatTreatmentNow==='subjecta'?normalized.reduce((sum,l)=>sum+l.qty*l.price*l.vat/100,0):0;
   const irpfRetention=Math.max(0,Math.min(100,+document.getElementById('fIrpf').value||0));
   const irpfAmount=+(subtotal*irpfRetention/100).toFixed(2);
   const total=+(subtotal+tax-irpfAmount).toFixed(2);
   const number=inv.number||`${bm.company.invoicePrefix||'F'}-${new Date(document.getElementById('fDate').value||today()).getFullYear()}-${String(bm.company.invoiceNext).padStart(4,'0')}`;
   const o={id,number,date:document.getElementById('fDate').value,customerId:customer?.id||'',customerName:customer?.name||'Client particular',customer:customer||null,lines:normalized,subtotal,tax,irpfRetention,irpfAmount,total,vatTreatment:vatTreatmentNow,sifApplicable,sifReason,notes:document.getElementById('fNotes').value,status:document.getElementById('fStatus').value,createdAt:inv.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),verifactuRecordId:inv.verifactuRecordId||'',verifactuNumber:inv.verifactuNumber||'',verifactuStatus:inv.verifactuStatus||'no_generat',verifactuHash:inv.verifactuHash||''};
   const ix=bm.invoices.findIndex(x=>x.id===id);
   if(ix>=0)bm.invoices[ix]=o; else {bm.company.invoiceNext++;bm.invoices.push(o);}
   if(sifApplicable&&!o.verifactuRecordId)createVerifactuRecord(o);
   saveBM();closeModal();renderBM();toast(`Factura ${number} guardada`);ensureInvoicePDF(o).then(()=>{saveBM();renderBM()})
 })}

function newExpense(){formModal('Nova despesa',`<div class="row"><div class="field"><label>Data</label><input id="fDate" type="date" value="${today()}"></div><div class="field"><label>Import (€)</label><input id="fAmount" type="number" step="0.01"></div></div><div class="field"><label>Concepte</label><input id="fDesc"></div><div class="field"><label>Categoria</label><select id="fCat"><option>Mercat</option><option>Transport</option><option>Materials</option><option>Publicitat</option><option>Serveis</option><option>Altres</option></select></div>`,()=>{const amount=+document.getElementById('fAmount').value||0;if(amount<=0)return toast('Import invàlid');bm.expenses.push({id:uid('exp'),date:document.getElementById('fDate').value,description:document.getElementById('fDesc').value.trim(),category:document.getElementById('fCat').value,amount});saveBM();closeModal();renderBM()})}
function newPurchase(){formModal('Factura de proveïdor',`<div class="row"><div class="field"><label>Data</label><input id="fDate" type="date" value="${today()}"></div><div class="field"><label>Base imposable (€)</label><input id="fBase" type="number" step="0.01"></div><div class="field"><label>IVA %</label><select id="fVat"><option>0</option><option>4</option><option>10</option><option selected>21</option></select></div></div><div class="row"><div class="field"><label>Proveïdor</label><input id="fSupplier"></div><div class="field"><label>NIF/CIF proveïdor</label><input id="fSupplierNif"></div><div class="field"><label>Número factura</label><input id="fNumber"></div></div><div class="row"><div class="field"><label>IVA deduïble (€)</label><input id="fDeductibleVat" type="number" step="0.01"></div><div class="field"><label>Tipus operació</label><select id="fOperation"><option>Interior</option><option>Intracomunitària</option><option>Importació</option><option>Exempta</option></select></div></div><div class="field"><label>Notes</label><textarea id="fNotes"></textarea></div>`,()=>{const base=+document.getElementById('fBase').value||0;const vat=+document.getElementById('fVat').value||0;if(base<=0)return toast('Base invàlida');const iva=base*vat/100;const total=base+iva;bm.purchaseInvoices.push({id:uid('pur'),date:document.getElementById('fDate').value,total,base,vat,iva,deductibleVat:+document.getElementById('fDeductibleVat').value||iva,supplier:document.getElementById('fSupplier').value.trim(),supplierNif:document.getElementById('fSupplierNif').value.trim(),number:document.getElementById('fNumber').value.trim(),operation:document.getElementById('fOperation').value,notes:document.getElementById('fNotes').value});saveBM();closeModal();renderBM()})}
function newCash(type){formModal(type==='in'?'Entrada de caixa':'Sortida de caixa',`<div class="row"><div class="field"><label>Data</label><input id="fDate" type="date" value="${today()}"></div><div class="field"><label>Import (€)</label><input id="fAmount" type="number" step="0.01"></div></div><div class="field"><label>Concepte</label><input id="fDesc"></div>`,()=>{const amount=+document.getElementById('fAmount').value||0;if(amount<=0)return toast('Import invàlid');bm.cash.push({id:uid('cash'),date:document.getElementById('fDate').value,type,amount,description:document.getElementById('fDesc').value.trim()});saveBM();closeModal();renderBM()})}
function newWorkshop(existing){const w=existing||{};formModal(existing?'Editar taller':'Nou taller',`<div class="field"><label>Nom</label><input id="fName" value="${esc(w.name)}"></div><div class="row"><div class="field"><label>Pax mín.</label><input id="fMin" type="number" value="${w.paxMin||1}"></div><div class="field"><label>Pax màx.</label><input id="fMax" type="number" value="${w.paxMax||12}"></div><div class="field"><label>Preu/pax</label><input id="fPrice" type="number" step="0.01" value="${w.pricePerPax||0}"></div></div><div class="row"><div class="field"><label>Cost material/pax</label><input id="fMat" type="number" step="0.01" value="${w.costMatPerPax||0}"></div><div class="field"><label>Cost fix/sessió</label><input id="fFix" type="number" step="0.01" value="${w.costFix||0}"></div></div><div class="field"><label>Descripció</label><textarea id="fDesc">${esc(w.desc||'')}</textarea></div>`,()=>{const o={id:w.id||uid('w'),name:document.getElementById('fName').value.trim(),paxMin:+document.getElementById('fMin').value||1,paxMax:+document.getElementById('fMax').value||12,pricePerPax:+document.getElementById('fPrice').value||0,costMatPerPax:+document.getElementById('fMat').value||0,costFix:+document.getElementById('fFix').value||0,desc:document.getElementById('fDesc').value,sessions:w.sessions||[],createdAt:w.createdAt||new Date().toISOString()};const ix=bm.workshops.findIndex(x=>x.id===o.id);if(ix>=0)bm.workshops[ix]=o;else bm.workshops.push(o);saveBM();closeModal();renderBM()})}
function addWorkshopSession(id){const w=bm.workshops.find(x=>x.id===id);if(!w)return;formModal('Nova sessió',`<div class="row"><div class="field"><label>Data</label><input id="fDate" type="date" value="${today()}"></div><div class="field"><label>Participants</label><input id="fPax" type="number" value="${w.paxMin||1}"></div></div><div class="field"><label>Nom / grup</label><input id="fName"></div>`,()=>{const pax=+document.getElementById('fPax').value||0;const gross=pax*w.pricePerPax;const cost=w.costFix+pax*w.costMatPerPax;w.sessions.push({id:uid('ws'),date:document.getElementById('fDate').value,name:document.getElementById('fName').value,pax,gross,cost,net:gross-cost,margin:gross?Math.round((gross-cost)/gross*100):0});saveBM();closeModal();renderBM()})}
function saveCompany(){const c=bm.company;c.name=document.getElementById('coName').value.trim();c.legalName=document.getElementById('coLegal').value.trim();c.nif=document.getElementById('coNif').value.trim();c.address=document.getElementById('coAddress').value.trim();c.postalCode=document.getElementById('coPostal').value.trim();c.city=document.getElementById('coCity').value.trim();c.email=document.getElementById('coEmail').value.trim();c.phone=document.getElementById('coPhone').value.trim();c.iban=document.getElementById('coIban').value.trim();c.invoicePrefix=document.getElementById('coPrefix').value.trim()||'F';c.defaultVat=+document.getElementById('coVat').value;c.invoiceFooter=document.getElementById('coFooter').value;saveBM();toast('Empresa guardada')}
function shopSale(id){const d=bm.shopDays.find(x=>x.id===id);if(!d)return;formModal('Venda botiga',`<div class="row"><div class="field"><label>Import (€)</label><input id="fAmount" type="number" step="0.01"></div><div class="field"><label>Mètode</label><select id="fMethod"><option>Efectiu</option><option>Targeta</option><option>Bizum</option></select></div></div><div class="field"><label>Concepte</label><input id="fDesc" placeholder="Venda / producte"></div>`,()=>{const a=+document.getElementById('fAmount').value||0;if(a<=0)return toast('Import invàlid');d.sales=+(d.sales+a).toFixed(2);d.movements=d.movements||[];d.movements.push({id:uid('sm'),type:'sale',amount:a,method:document.getElementById('fMethod').value,description:document.getElementById('fDesc').value});saveBM();closeModal();renderBM()})}
function shopCost(id){const d=bm.shopDays.find(x=>x.id===id);if(!d)return;formModal('Cost botiga',`<div class="row"><div class="field"><label>Import (€)</label><input id="fAmount" type="number" step="0.01"></div><div class="field"><label>Concepte</label><input id="fDesc"></div></div>`,()=>{const a=+document.getElementById('fAmount').value||0;if(a<=0)return toast('Import invàlid');d.costs=+(d.costs+a).toFixed(2);d.movements=d.movements||[];d.movements.push({id:uid('sc'),type:'cost',amount:a,description:document.getElementById('fDesc').value});saveBM();closeModal();renderBM()})}
function openShop(){const existing=bm.shopDays.find(x=>x.date===today());if(existing&&!existing.closed){toast('La botiga ja està oberta');return}bm.shopDays.push({id:uid('shop'),date:today(),openedAt:new Date().toISOString(),closed:false,sales:0,costs:0,notes:''});saveBM();renderBM();toast('Botiga oberta')}
function closeShop(id){const d=bm.shopDays.find(x=>x.id===id);if(!d)return;d.sales=(window.calcFin?window.calcFin().gross:0);d.costs=(window.calcFin?window.calcFin().totalCosts:0);d.closed=true;d.closedAt=new Date().toISOString();saveBM();renderBM();toast('Dia de botiga tancat')}
function editClient(id){const c=bm.customers.find(x=>x.id===id);if(c)newClient(c)}
function editWorkshop(id){const w=bm.workshops.find(x=>x.id===id);if(w)newWorkshop(w)}
function invoiceActions(id){const i=bm.invoices.find(x=>x.id===id);if(!i)return;formModal(`Factura ${i.number}`,`<div class="actions"><button class="btn btn-primary" onclick="BM.downloadInvoice('${i.id}')">↓ PDF</button><button class="btn btn-ghost" onclick="BM.shareInvoice('${i.id}')">✉ Compartir / correu</button><button class="btn btn-ghost" onclick="BM.editInvoice('${i.id}')">Editar</button></div><div class="small" style="margin-top:12px">${fmtDate(i.date)} · ${esc(i.customerName)} · Base ${eur(i.subtotal)} · IVA ${eur(i.tax)}${i.irpfAmount?` · IRPF -${eur(i.irpfAmount)}`:''} · <strong>${eur(i.total)}</strong></div><div class="small muted" style="margin-top:8px">IVA: ${esc(i.vatTreatment||'subjecta')} · VERI*FACTU: ${i.sifApplicable?esc(i.verifactuNumber||i.verifactuStatus||'pendent'):'fora d’àmbit'}</div>`,()=>BM.closeModal())}
function editInvoice(id){const i=bm.invoices.find(x=>x.id===id);closeModal();setTimeout(()=>newInvoice(i),80)}
function pdfBytes(invoice){const lines=[];const c=bm.company, cust=invoice.customer||{};lines.push(c.name,c.legalName,c.nif,c.address,`${c.postalCode} ${c.city}`,c.email,'');lines.push(`FACTURA ${invoice.number}`,`Fecha: ${fmtDate(invoice.date)}`,'');lines.push(`Cliente: ${invoice.customerName}`,cust.nif||'',cust.address||'',`${cust.postalCode||''} ${cust.city||''}`,'');lines.push('DESCRIPCIO                    CANT.     PREU       IVA      IMPORT');invoice.lines.forEach(l=>lines.push(`${l.description.slice(0,28).padEnd(30)} ${String(l.qty).padStart(5)} ${eur(l.price).padStart(12)} ${String(l.vat+'%').padStart(6)} ${eur(l.qty*l.price).padStart(12)}`));lines.push('',`Base imposable: ${eur(invoice.subtotal)}`,`IVA (${invoice.vatTreatment==='subjecta'?'subjecta':'0% / '+invoice.vatTreatment}): ${eur(invoice.tax)}`);if(invoice.irpfAmount)lines.push(`Retenció IRPF (${invoice.irpfRetention}%): -${eur(invoice.irpfAmount)}`);lines.push(`TOTAL: ${eur(invoice.total)}`,'',c.invoiceFooter||'');return makePDF(lines,`${invoice.number}.pdf`)}
function makePDF(lines,name){const enc=new TextEncoder();const clean=s=>String(s||'').replace(/[^\x20-\x7EÀ-ÿ]/g,'?').replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)');let y=800,content='BT /F1 10 Tf 45 0 0 45 50 0 Tm\n';for(const line of lines){if(y<45){content+='ET';break}content+=`1 0 0 1 0 ${y-50} Tm (${clean(line)}) Tj\n`;y-=16}content+='ET';const objs=[];objs[1]='<< /Type /Catalog /Pages 2 0 R >>';objs[2]='<< /Type /Pages /Kids [3 0 R] /Count 1 >>';objs[3]='<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>';objs[4]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';objs[5]=`<< /Length ${enc.encode(content).length} >>\nstream\n${content}\nendstream`;let pdf='%PDF-1.4\n',offs=[0];for(let i=1;i<objs.length;i++){offs[i]=enc.encode(pdf).length;pdf+=`${i} 0 obj\n${objs[i]}\nendobj\n`}const xref=enc.encode(pdf).length;pdf+=`xref\n0 ${objs.length}\n0000000000 65535 f \n`;for(let i=1;i<objs.length;i++)pdf+=String(offs[i]).padStart(10,'0')+' 00000 n \n';pdf+=`trailer\n<< /Size ${objs.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;return new File([pdf],name,{type:'application/pdf'})}
function fileToDataURL(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
async function ensureInvoicePDF(i){if(i.pdfData)return new File([Uint8Array.from(atob(i.pdfData.split(',')[1]),c=>c.charCodeAt(0))],i.number+'.pdf',{type:'application/pdf'});const f=pdfBytes(i);try{i.pdfData=await fileToDataURL(f);i.pdfGeneratedAt=new Date().toISOString();saveBM()}catch(e){}return f}
async function downloadInvoice(id){const i=bm.invoices.find(x=>x.id===id);if(!i)return;const f=await ensureInvoicePDF(i);const a=document.createElement('a');a.href=URL.createObjectURL(f);a.download=f.name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('PDF generat')}
async function shareInvoice(id){const i=bm.invoices.find(x=>x.id===id);if(!i)return;const f=await ensureInvoicePDF(i);try{if(navigator.share&&navigator.canShare&&navigator.canShare({files:[f]})){await navigator.share({title:`Factura ${i.number}`,text:`Factura ${i.number} de ${bm.company.name}`,files:[f]});return}}catch(e){}downloadInvoice(id);const email=i.customer?.email||'';if(email)location.href=`mailto:${encodeURIComponent(email)}?subject=${encodeURIComponent('Factura '+i.number)}&body=${encodeURIComponent('Adjunto trobaràs la factura '+i.number+'.')}`}
function newInvoiceForCustomer(c){newInvoice({customerId:c.id,customerName:c.name,customer:c})}
function exportInvoicesCSV(){const rows=[['Número','Data','Client','Base','IVA','Retenció IRPF','Total','Estat','IVA tractament','VERI*FACTU'],...bm.invoices.map(i=>[i.number,i.date,i.customerName,i.subtotal,i.tax,i.irpfAmount||0,i.total,i.status,i.vatTreatment||'',i.sifApplicable?'Sí':'No'])];const csv=rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(';')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='factures.csv';a.click()}
function toggleSifFields(){const v=document.getElementById('fSif')?.value==='true';const b=document.getElementById('sifReasonBox');if(b)b.style.display=v?'none':'block'}
async function sha256Hex(text){if(window.crypto?.subtle){const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));return [...new Uint8Array(buf)].map(x=>x.toString(16).padStart(2,'0')).join('')}return btoa(unescape(encodeURIComponent(text))).slice(0,64)}
async function createVerifactuRecord(invoice){
 if(!invoice?.sifApplicable)return;
 bm.verifactu=bm.verifactu||{records:[],events:[],lastHash:'',nextNumber:1,sequenceYear:new Date().getFullYear()};
 const year=new Date(invoice.date||today()).getFullYear();
 if(bm.verifactu.sequenceYear!==year){
   const existing=bm.verifactu.records.filter(r=>new Date(r.payload?.invoiceDate||r.createdAt).getFullYear()===year);
   bm.verifactu.sequenceYear=year;
   bm.verifactu.nextNumber=existing.length+1;
 }
 const vfNumber=`VF-${year}-${String(bm.verifactu.nextNumber++).padStart(6,'0')}`;
 const prev=bm.verifactu.lastHash||'';
 const payload={id:invoice.id,verifactuNumber:vfNumber,invoiceNumber:invoice.number,invoiceDate:invoice.date,issuerNif:bm.company.nif,customerNif:invoice.customer?.nif||'',total:invoice.total,vat:invoice.tax,vatTreatment:invoice.vatTreatment||'subjecta',type:'F1',previousHash:prev,timestamp:new Date().toISOString()};
 const hash=await sha256Hex(JSON.stringify(payload));
 const rec={id:uid('vrf'),invoiceId:invoice.id,number:invoice.number,verifactuNumber:vfNumber,createdAt:payload.timestamp,payload,hash,previousHash:prev,status:'pending',submittedAt:'',responseId:'',response:''};
 bm.verifactu.records.push(rec);bm.verifactu.lastHash=hash;
 invoice.verifactuRecordId=rec.id;invoice.verifactuNumber=vfNumber;invoice.verifactuHash=hash;invoice.verifactuStatus='pending';saveBM();
}
function verifactu(){const vf=bm.verifactu||{records:[],events:[],lastHash:''};const pending=vf.records.filter(r=>r.status==='pending').length;const accepted=vf.records.filter(r=>r.status==='accepted').length;const outside=bm.invoices.filter(i=>i.sifApplicable===false).length;return card('🧾 VERI*FACTU',`<div class="fin-grid2"><div class="fin-big"><div class="fin-big-label">Pendents de remissió</div><div class="fin-big-val accent">${pending}</div></div><div class="fin-big"><div class="fin-big-label">Acceptats AEAT</div><div class="fin-big-val green">${accepted}</div></div><div class="fin-big"><div class="fin-big-label">Fora d'àmbit</div><div class="fin-big-val blue">${outside}</div></div><div class="fin-big"><div class="fin-big-label">Cadena actual</div><div class="fin-big-val purple" style="font-size:12px">${vf.lastHash?vf.lastHash.slice(0,16)+'…':'—'}</div></div></div>`)+card('Configuració SIF',`<div class="row"><div class="field"><label>Modalitat</label><select onchange="BM.saveSifMode(this.value)"><option value="verifactu" ${bm.company.sifMode==='verifactu'?'selected':''}>VERI*FACTU</option><option value="no_verifactu" ${bm.company.sifMode==='no_verifactu'?'selected':''}>NO VERI*FACTU</option></select></div><div class="field"><label>Per defecte en noves factures</label><select onchange="BM.saveSifDefault(this.value)"><option value="true" ${bm.company.sifDefaultApplicable!==false?'selected':''}>Incloure</option><option value="false" ${bm.company.sifDefaultApplicable===false?'selected':''}>No incloure</option></select></div></div><div class="small muted">L'opció de cada factura preval sobre aquest valor. «Fora d'àmbit» no significa «IVA 0»: les operacions exemptes o no subjectes poden continuar havent-se de registrar si existeix obligació de factura.</div>`)+card('Registres de facturació',`<div class="actions"><button class="btn btn-primary" onclick="BM.exportVerifactuCSV()">↓ Exportar registres</button><button class="btn btn-ghost" onclick="BM.markPendingForReview()">↻ Revisar pendents</button></div><div class="table-scroll" style="margin-top:12px"><table><thead><tr><th>Identificador VERI*FACTU</th><th>Factura</th><th>Hash</th><th>Estat</th><th>Data</th></tr></thead><tbody>${vf.records.slice().reverse().map(r=>`<tr><td><strong>${esc(r.verifactuNumber||'—')}</strong></td><td>${esc(r.number)}</td><td style="font-family:monospace;font-size:11px">${esc(r.hash.slice(0,18))}…</td><td>${esc(r.status)}</td><td>${new Date(r.createdAt).toLocaleString('ca-ES')}</td></tr>`).join('')||'<tr><td colspan="5">Sense registres</td></tr>'}</tbody></table></div>`)+card('Important',`<div class="small">Aquesta versió prepara i conserva el registre, l'encadenament i la cua de remissió. La connexió efectiva amb els serveis de l'AEAT, amb les especificacions tècniques i l'autenticació corresponents, s'ha de completar abans d'utilitzar-la com a SIF VERI*FACTU en producció.</div>`)}
function saveSifMode(v){bm.company.sifMode=v;saveBM();toast('Modalitat SIF guardada')}
function saveSifDefault(v){bm.company.sifDefaultApplicable=v==='true';saveBM();toast('Predeterminat VERI*FACTU guardat')}
function markPendingForReview(){toast(`${(bm.verifactu?.records||[]).filter(r=>r.status==='pending').length} registres pendents de revisió`)}
function exportVerifactuCSV(){const rows=[['ID registre','Identificador VERI*FACTU','Factura','Data','NIF emissor','Total','IVA','Hash anterior','Hash','Estat'],...(bm.verifactu?.records||[]).map(r=>[r.id,r.verifactuNumber||'',r.number,r.createdAt,r.payload.issuerNif,r.payload.total,r.payload.vat,r.previousHash,r.hash,r.status])];const csv=rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(';')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`todavia-verifactu-${today()}.csv`;a.click()}

function fiscal(){
 const y=new Date().getFullYear(), ty=taxYear(y);
 const profile=`<div class="row"><div class="field"><label>Règim IVA</label><select id="taxRegime" onchange="BM.saveTaxProfile()"><option value="general" ${bm.company.taxRegime==='general'?'selected':''}>Règim general</option><option value="simplificado" ${bm.company.taxRegime==='simplificado'?'selected':''}>Règim simplificat</option><option value="recargo" ${bm.company.taxRegime==='recargo'?'selected':''}>Recàrrec d’equivalència</option><option value="otro" ${bm.company.taxRegime==='otro'?'selected':''}>Altre</option></select></div><div class="field"><label>IRPF</label><select id="irpfMethod" onchange="BM.saveTaxProfile()"><option value="directa" ${bm.company.irpfMethod==='directa'?'selected':''}>Estimació directa</option><option value="modulos" ${bm.company.irpfMethod==='modulos'?'selected':''}>Mòduls</option><option value="no" ${bm.company.irpfMethod==='no'?'selected':''}>No aplica</option></select></div><div class="field"><label>Retenció IRPF (%)</label><input id="irpfRetention" type="number" step="0.01" value="${bm.company.irpfRetention||0}" onchange="BM.saveTaxProfile()"></div></div><div class="small muted">Pre-càlcul fiscal a partir de les dades introduïdes. La presentació oficial es fa a l’AEAT. Règims especials, prorrata, béns d’inversió i operacions intracomunitàries requereixen revisió.</div>`;
 const quarters=[1,2,3,4].map(n=>fiscalQuarterRow(y,n)).join('');
 return card('🧮 Fiscalitat i obligacions',`<div class="fin-grid2"><div class="fin-big"><div class="fin-big-label">IVA repercutit ${y}</div><div class="fin-big-val accent">${eur(ty.outputVat)}</div></div><div class="fin-big"><div class="fin-big-label">IVA deduïble ${y}</div><div class="fin-big-val green">${eur(ty.inputVat)}</div></div><div class="fin-big"><div class="fin-big-label">IVA diferencial</div><div class="fin-big-val blue">${eur(ty.outputVat-ty.inputVat)}</div></div><div class="fin-big"><div class="fin-big-label">Rendiment IRPF orientatiu</div><div class="fin-big-val purple">${eur(ty.irpfResult)}</div></div></div>`)+card('Perfil fiscal',profile)+card('Calendari trimestral',`<div class="table-scroll"><table><thead><tr><th>Període</th><th>IVA 303</th><th>IRPF 130/131</th><th>Retencions</th><th>Estat</th></tr></thead><tbody>${quarters}</tbody></table></div>`)+card('Llibres i models',`<div class="actions"><button class="btn btn-primary" onclick="BM.exportFiscalCSV('issued')">↓ Llibre factures emeses</button><button class="btn btn-ghost" onclick="BM.exportFiscalCSV('received')">↓ Llibre factures rebudes</button><button class="btn btn-ghost" onclick="BM.exportFiscalCSV('vat')">↓ Resum IVA</button><button class="btn btn-ghost" onclick="BM.exportFiscalCSV('irpf')">↓ Resum IRPF</button></div><div class="actions" style="margin-top:10px"><button class="btn btn-ghost" onclick="window.open('https://sede.agenciatributaria.gob.es/','_blank')">AEAT</button><button class="btn btn-ghost" onclick="window.open('https://sede.agenciatributaria.gob.es/Sede/procedimientoini/G414.shtml','_blank')">Model 303</button><button class="btn btn-ghost" onclick="window.open('https://sede.agenciatributaria.gob.es/Sede/procedimientoini/G601.shtml','_blank')">Model 130</button></div>`)+card('Control fiscal',`<div class="small">El mòdul centralitza la informació necessària per preparar les liquidacions: ingressos, factures emeses, factures rebudes, IVA repercutit, IVA deduïble, despeses i IRPF. No envia automàticament la declaració a l’AEAT.</div>`);
}
function quarterFor(d){const m=new Date(d+'T12:00:00').getMonth()+1;return Math.ceil(m/3)}
function qRange(y,q){return {from:`${y}-${String((q-1)*3+1).padStart(2,'0')}-01`,to:`${y}-${String(q*3).padStart(2,'0')}-${q===4?'31':new Date(y,q*3,0).getDate()}`}}
function inRange(d,r){return d>=r.from&&d<=r.to}
function taxQuarter(y,q){const r=qRange(y,q);const issued=bm.invoices.filter(i=>i.status!=='cancel·lada'&&inRange(i.date,r));const received=bm.purchaseInvoices.filter(i=>inRange(i.date,r));const output=issued.reduce((s,i)=>s+(i.tax||0),0);const retentions=issued.reduce((s,i)=>s+(i.irpfAmount||0),0);const input=received.reduce((s,i)=>s+(i.deductibleVat!==undefined?i.deductibleVat:(i.iva||0)),0);const income=issued.reduce((s,i)=>s+(i.subtotal||0),0);const expenses=received.reduce((s,i)=>s+(i.base!==undefined?i.base:((i.total||0)/(1+(i.vat||0)/100))),0)+bm.expenses.filter(e=>inRange(e.date,r)).reduce((s,e)=>s+(e.amount||0),0);return {issued,received,output,input,retentions,income,expenses,vat:output-input,irpfResult:Math.max(0,income-expenses)}}
function taxYear(y){let z={outputVat:0,inputVat:0,irpfResult:0};for(let q=1;q<=4;q++){const t=taxQuarter(y,q);z.outputVat+=t.output;z.inputVat+=t.input;z.irpfResult+=t.irpfResult}return z}
function fiscalQuarterRow(y,q){const t=taxQuarter(y,q);const deadline=q===4?`30/01/${y+1}`:`20/${String(q*3+1).padStart(2,'0')}/${y}`;const status=t.vat>0?'Pendent de revisió':'Revisar';return `<tr><td>${y} T${q}</td><td><b>${eur(t.vat)}</b><div class="muted">303 · ${deadline}</div></td><td><b>${eur(t.irpfResult)}</b><div class="muted">${bm.company.irpfMethod==='modulos'?'131':'130'} · ${deadline}</div></td><td>Revisar</td><td>${status}</td></tr>`}
function renderFiscal(){return}
function saveTaxProfile(){bm.company.taxRegime=document.getElementById('taxRegime').value;bm.company.irpfMethod=document.getElementById('irpfMethod').value;bm.company.irpfRetention=+document.getElementById('irpfRetention').value||0;saveBM();toast('Perfil fiscal guardat')}
function exportFiscalCSV(type){const y=new Date().getFullYear();let rows=[];if(type==='issued')rows=[['Número','Data','Client','NIF','Base','IVA','Total'],...bm.invoices.filter(i=>i.status!=='cancel·lada'&&new Date(i.date).getFullYear()===y).map(i=>[i.number,i.date,i.customerName,i.customer?.nif||'',i.subtotal,i.tax,i.total])];if(type==='received')rows=[['Data','Proveïdor','NIF','Número','Base','IVA','IVA deduïble','Total','Operació'],...bm.purchaseInvoices.filter(i=>new Date(i.date).getFullYear()===y).map(i=>[i.date,i.supplier,i.supplierNif||'',i.number,i.base??'',i.iva??i.vat?((i.base||0)*(i.vat||0)/100):'',i.deductibleVat??'',i.total,i.operation||''])];if(type==='vat')rows=[['Any','IVA repercutit','IVA deduïble','Diferència'],...Array.from({length:4},(_,i)=>{const t=taxQuarter(y,i+1);return [`${y} T${i+1}`,t.output,t.input,t.vat]})];if(type==='irpf')rows=[['Any','Ingressos','Despeses','Retencions IRPF','Rendiment orientatiu'],...Array.from({length:4},(_,i)=>{const t=taxQuarter(y,i+1);return [`${y} T${i+1}`,t.income,t.expenses,t.retentions,t.irpfResult]})];const csv=rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(';')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`todavia-fiscal-${type}-${y}.csv`;a.click();}
function exportData(){const blob=new Blob([JSON.stringify(bm,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`todavia-negoci-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Còpia de gestió exportada')}
function importData(ev){const f=ev.target.files&&ev.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(!x.company||!x.invoices)throw Error('Fitxer no compatible');bm=Object.assign(def(),x);saveBM();renderBM();toast('Gestió restaurada')}catch(e){toast('Fitxer no vàlid: '+e.message)}};r.readAsText(f);ev.target.value=''}
function quickSave(){saveBM();toast('Gestió guardada al dispositiu')}
async function syncAll(){if(!window.settings?.scriptUrl && typeof settings==='undefined'){toast('Configura primer Google Sheets');return}const url=(typeof settings!=='undefined'&&settings.scriptUrl)||'';if(!url){toast('Configura primer Google Sheets');return}const payload={action:'syncBusiness',eventId:uid('bm'),timestamp:new Date().toISOString(),deviceId:window.deviceId||'',deviceName:window.deviceName||'',business:bm};try{const r=await fetch(url,{method:'POST',headers:{'Content-Type':'text/plain'},body:JSON.stringify(payload)});const j=await r.json();if(j.status==='ok'){bm.pending=[];saveBM();toast('✓ Gestió sincronitzada a Sheets/Drive')}else throw Error(j.message||'Error')}catch(e){bm.pending.push({payload,error:e.message,ts:new Date().toISOString()});saveBM();toast('📴 Guardat al mòbil; sync pendent')}}
window.BM={openBusiness,renderBM,newClient,editClient,newInvoice,editInvoice,newExpense,newPurchase,newCash,newWorkshop,editWorkshop,addWorkshopSession,saveCompany,openShop,closeShop,invoiceActions,downloadInvoice,shareInvoice,exportInvoicesCSV,quickSave,exportData,importData,syncAll,shopSale,shopCost,shopCalcAdd,shopCalcRender,shopCalcClear,shopCalcCheckout,shopCalcCustom,saveTaxProfile,saveSifMode,saveSifDefault,toggleSifFields,exportVerifactuCSV,markPendingForReview,exportFiscalCSV,closeModal:()=>document.getElementById('bmModal')?.remove(),renderInvoiceRows};
window.addEventListener('load',ensureUI);document.addEventListener('DOMContentLoaded',ensureUI);
})();
